import java.net.URL;

public class SecureExample {
    public static void main(String[] args) {
        String userInput = "http://internal-api:8080/secret-data"; // Malicious input
        try {
            // Validate the URL to prevent SSRF attacks
            if (isValidUrl(userInput)) {
                URL url = new URL(userInput);
                System.out.println("Accessing: " + url.toString());
            } else {
                System.out.println("Invalid or potentially malicious URL.");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // Validate URL to prevent SSRF and other injection attacks
    private static boolean isValidUrl(String input) {
        // Simple validation: check if the URL starts with http:// or https://
        // In a real-world scenario, more robust validation is needed
        return input != null && input.startsWith("http://") && !input.contains("localhost") && !input.contains("internal-api");
    }
